import {defineComponent,h,mergeProps} from 'vue';
import {YkButton} from '../../components/button/index.js';
import {YkCard} from '../../components/card/index.js';
const section=(name,render)=>defineComponent({name,inheritAttrs:false,props:{label:String,description:String,items:{type:Array,default:()=>[]},actionLabel:String,secondaryLabel:String,layout:{type:String,default:'center'},brand:String},emits:['action'],setup(p,{attrs,emit}){return()=>h('section',mergeProps(attrs,{class:['yk-section','yk-section--'+name.replace('Yk','').toLowerCase(),'is-'+p.layout]}),render(p,(action,value)=>emit('action',{action,value})));}});
export const YkFeatureGrid=section('YkFeatureGrid',(p,fire)=>[h('div',{class:'yk-section__head'},[h('h2',{},p.label||'能力，一眼看清'),h('p',{},p.description||'把核心价值拆成可扫描的小块。')]),h('div',{class:'yk-feature-grid'},(p.items.length?p.items:[{label:'一致设计',content:'统一 Token 与组件规则。'},{label:'真实代码',content:'预览与业务使用同源。'},{label:'可持续扩展',content:'组件、区块、页面、动效分层维护。'}]).map((x,i)=>h(YkCard,{title:x.label||`能力 ${i+1}`,description:x.content||'可复用说明'},{default:()=>h('span',{class:'yk-section__index'},String(i+1).padStart(2,'0'))}))) ]);
export const YkStats=section('YkStats',(p)=>[h('div',{class:'yk-section__head'},[h('h2',{},p.label||'关键数字'),h('p',{},p.description||'用少量数字建立信息锚点。')]),h('div',{class:'yk-stats'},(p.items.length?p.items:[{label:'组件',content:'32+'},{label:'区块',content:'15+'},{label:'模板',content:'12+'}]).map(x=>h('div',{},[h('strong',{},x.content||'—'),h('span',{},x.label)]))) ]);
export const YkLogoCloud=section('YkLogoCloud',(p)=>[h('p',{class:'yk-section__overline'},p.label||'适配你的技术栈'),h('div',{class:'yk-logo-cloud'},(p.items.length?p.items:[{label:'Vue'},{label:'Vite'},{label:'TypeScript'},{label:'Reka UI'},{label:'Playwright'}]).map(x=>h('span',{},x.label))) ]);
export const YkPricing=section('YkPricing',(p,fire)=>[h('div',{class:'yk-section__head'},[h('h2',{},p.label||'选择适合你的方案'),h('p',{},p.description||'价格只是示例，真正业务金额由项目传入。')]),h('div',{class:'yk-pricing'},(p.items.length?p.items:[{label:'基础版',content:'适合个人项目'},{label:'团队版',content:'共享主题与资产'},{label:'企业版',content:'私有分发与治理'}]).map((x,i)=>h(YkCard,{title:x.label,description:x.content,variant:i===1?'elevated':'outlined'},{default:()=>h('div',{class:'yk-price'},i===0?'¥0':i===1?'¥99':'定制'),footer:()=>h(YkButton,{variant:i===1?'primary':'outline',onClick:()=>fire('select',x.label)},()=>p.actionLabel||'选择方案')}))) ]);
export const YkFaq=section('YkFaq',(p)=>[h('div',{class:'yk-section__head'},[h('h2',{},p.label||'常见问题'),h('p',{},p.description||'把高频疑问放在决策路径附近。')]),h('div',{class:'yk-faq'},(p.items.length?p.items:[{label:'可以改样式吗？',content:'可以，通过主题、同类默认和实例三级配置。'},{label:'能直接用于 Vue 项目吗？',content:'可以，组件包和导出代码都基于 Vue。'}]).map(x=>h('details',{},[h('summary',{},x.label),h('p',{},x.content)]))) ]);
export const YkTestimonials=section('YkTestimonials',(p)=>[h('div',{class:'yk-section__head'},[h('h2',{},p.label||'来自真实使用场景的反馈'),h('p',{},p.description||'案例文本请替换为你自己的真实内容。')]),h('div',{class:'yk-testimonials'},(p.items.length?p.items:[{label:'产品团队',content:'统一组件以后，页面返工明显减少。'},{label:'研发团队',content:'同一套参数可以直接复用到业务项目。'}]).map(x=>h('blockquote',{},[h('p',{},'“'+x.content+'”'),h('footer',{},x.label)]))) ]);
export const YkNewsletter=section('YkNewsletter',(p,fire)=>[h('div',{class:'yk-section__head'},[h('h2',{},p.label||'获取更新'),h('p',{},p.description||'留下邮箱，收到组件库与设计资产的更新。')]),h('form',{class:'yk-newsletter',onSubmit:e=>{e.preventDefault();fire('submit',new FormData(e.currentTarget).get('email'))}},[h('input',{name:'email',type:'email',required:true,placeholder:'name@example.com','aria-label':'邮箱'}),h(YkButton,{type:'submit'},()=>p.actionLabel||'订阅')]) ]);
export const YkContact=section('YkContact',(p,fire)=>[h('div',{class:'yk-section__head'},[h('h2',{},p.label||'和我们聊聊'),h('p',{},p.description||'适合联系、咨询、合作等简单入口。')]),h('div',{class:'yk-contact'},[h('div',{},[h('strong',{},'项目咨询'),h('p',{},'说明你的目标、页面类型和技术环境。')]),h(YkButton,{onClick:()=>fire('contact')},()=>p.actionLabel||'发起联系')]) ]);
export const YkSteps=section('YkSteps',(p)=>[h('div',{class:'yk-section__head'},[h('h2',{},p.label||'三步完成'),h('p',{},p.description||'把长流程压缩成清晰的阶段。')]),h('ol',{class:'yk-steps'},(p.items.length?p.items:[{label:'选择资产',content:'组件、区块、模板或动效。'},{label:'调整参数',content:'实时预览并保存方案。'},{label:'导出使用',content:'带到你的 Vue 项目。'}]).map((x,i)=>h('li',{},[h('span',{},i+1),h('div',{},[h('strong',{},x.label),h('p',{},x.content)])]))) ]);
export const YkBentoGrid=section('YkBentoGrid',(p)=>[h('div',{class:'yk-section__head'},[h('h2',{},p.label||'Bento 信息区'),h('p',{},p.description||'不同跨度的卡片形成更有节奏的产品展示。')]),h('div',{class:'yk-bento'},(p.items.length?p.items:[{label:'主题',content:'全局 Token'},{label:'组件',content:'Vue 原生'},{label:'页面',content:'快速组合'},{label:'动效',content:'可复用 Recipe'}]).map((x,i)=>h('article',{class:{'is-wide':i===0}},[h('small',{},String(i+1).padStart(2,'0')),h('h3',{},x.label),h('p',{},x.content)]))) ]);
